//! Research-profile basis transport shared by candidate prover and verifier.
//! No production caller and no privacy claim. The source mask inventory
//! determines the immutable map; no prover-supplied permutation is accepted.
use aspis_core::field::{M31, QM31};
use aspis_statement::pool_v1::{
    pool_v1_pair_forest_copy_active_rows_v1, pool_v1_pair_forest_relation_free_mask_cells_v1,
};
use std::sync::OnceLock;

pub const N: usize = 1024;
pub const PIVOT: usize = 1023;
pub const PADS: usize = 89;

pub trait Scalar: Copy {
    const ZERO: Self;
    fn plus(self, rhs: Self) -> Self;
    fn minus(self, rhs: Self) -> Self;
}
impl Scalar for M31 {
    const ZERO: Self = M31::ZERO;
    fn plus(self, rhs: Self) -> Self {
        self.add(rhs)
    }
    fn minus(self, rhs: Self) -> Self {
        self.sub(rhs)
    }
}
impl Scalar for QM31 {
    const ZERO: Self = QM31::ZERO;
    fn plus(self, rhs: Self) -> Self {
        self.add(rhs)
    }
    fn minus(self, rhs: Self) -> Self {
        self.sub(rhs)
    }
}

pub struct Transport {
    pub(crate) order: Vec<usize>,
    pub(crate) inactive: Vec<bool>,
}
impl Transport {
    pub fn new() -> Self {
        let active = pool_v1_pair_forest_copy_active_rows_v1().unwrap();
        let inactive: Vec<_> = (0..N).map(|r| !active.contains(&(r as u16))).collect();
        let cells = pool_v1_pair_forest_relation_free_mask_cells_v1().unwrap();
        let legal = |r: usize| {
            (0..16).all(|c| {
                cells
                    .iter()
                    .any(|cell| usize::from(cell.column) == c && usize::from(cell.row) == r)
            })
        };
        assert!(inactive[PIVOT] && legal(PIVOT));
        let pads: Vec<_> = (0..PIVOT)
            .filter(|&r| inactive[r] && r != 1014 && legal(r))
            .take(PADS)
            .collect();
        assert_eq!(pads.len(), PADS);
        let mut order = pads.clone();
        order.extend((0..PIVOT).filter(|r| !pads.contains(r)));
        order.push(PIVOT);
        Self { order, inactive }
    }
    pub fn forward<F: Scalar>(&self, m: &[F]) -> Vec<F> {
        assert_eq!(m.len(), N);
        let mut out: Vec<_> = self.order.iter().map(|&r| m[r]).collect();
        out[PIVOT] = (0..N)
            .filter(|&r| self.inactive[r])
            .fold(F::ZERO, |a, r| a.plus(m[r]));
        out
    }
    pub fn inverse<F: Scalar>(&self, t: &[F]) -> Vec<F> {
        assert_eq!(t.len(), N);
        let mut m = vec![F::ZERO; N];
        for (j, &r) in self.order.iter().enumerate() {
            m[r] = t[j];
        }
        let other = (0..PIVOT)
            .filter(|&r| self.inactive[r])
            .fold(F::ZERO, |a, r| a.plus(m[r]));
        m[PIVOT] = t[PIVOT].minus(other);
        m
    }
    pub fn dual<F: Scalar>(&self, w: &[F]) -> Vec<F> {
        assert_eq!(w.len(), N);
        self.order
            .iter()
            .map(|&r| {
                if r != PIVOT && self.inactive[r] {
                    w[r].minus(w[PIVOT])
                } else {
                    w[r]
                }
            })
            .collect()
    }
}
pub fn transport() -> &'static Transport {
    static T: OnceLock<Transport> = OnceLock::new();
    T.get_or_init(Transport::new)
}

//! Shared research opening weights, used verbatim by focused tests and host.
use super::{
    basis_transport::{transport, N},
    corelib::{
        field::{M31, M31_HALF, QM31 as K},
        sumcheck::WeightAccumulator,
        v6_transcript::v6_statement_points,
    },
};

fn xt(v: &[K], n: usize) -> Vec<K> {
    (0..n)
        .map(|j| {
            let (mut row, mut bit, mut scale, mut sum) = (j, 0, M31::ONE, K::ZERO);
            while row & (1 << bit) != 0 {
                row ^= 1 << bit;
                scale = scale.mul(M31_HALF);
                sum = sum.add(v[row].mul_m31(scale));
                bit += 1;
            }
            sum.add(v[row | (1 << bit)].mul_m31(scale))
        })
        .collect()
}
pub(super) fn chord_transpose(w: &[K], [a, b, c]: [K; 3]) -> Vec<K> {
    assert_eq!(w.len(), N);
    let mut w = w.to_vec();
    w.resize(1028, K::ZERO);
    let wa: Vec<_> = w.chunks_exact(2).map(|v| v[0]).collect();
    let wb: Vec<_> = w.chunks_exact(2).map(|v| v[1]).collect();
    let xwa = xt(&wa, 513);
    let xxwa = xt(&xwa, 512);
    let xwb = xt(&wb, 512);
    let mut out = vec![K::ZERO; N];
    for j in 0..512 {
        out[2 * j] = a.mul(wa[j]).add(b.mul(xwa[j])).add(c.mul(wb[j]));
        out[2 * j + 1] = c
            .mul(wa[j].sub(xxwa[j]))
            .add(a.mul(wb[j]))
            .add(b.mul(xwb[j]));
    }
    out
}
pub(super) fn original_weights(z: &[K; 10], kappa: K, structured: bool) -> Vec<K> {
    let scales = [kappa, kappa.square(), kappa.square().mul(kappa)];
    let mut w = WeightAccumulator::empty(10);
    for (i, p) in v6_statement_points(z).into_iter().enumerate() {
        if !(structured && i == 0) {
            w.add_multilinear(scales[i], p.to_vec()).unwrap();
        }
    }
    let g = structured.then(|| super::structured_g::mask_weights(z));
    (0..N)
        .map(|i| {
            let mut v = w.weight_at(i as u32);
            if transport().inactive[i] {
                v = v.add(K::ONE);
            }
            if let Some(g) = &g {
                v = v.add(kappa.mul(g[i]));
            }
            v
        })
        .collect()
}
pub(super) fn quotient_weights(
    z: &[K; 10],
    kappa: K,
    abc: [K; 3],
    tau: K,
    structured: bool,
) -> WeightAccumulator {
    let mut w = chord_transpose(
        &transport().dual(&original_weights(z, kappa, structured)),
        abc,
    );
    let t = if structured { tau.pow(3) } else { tau };
    let tt = if structured { tau.pow(4) } else { tau.square() };
    w[1023] = w[1023].add(t);
    w[1022] = w[1022].add(tt.mul(abc[1]));
    w[1021] = w[1021].sub(tt.mul(abc[2]));
    let mut out = WeightAccumulator::empty(10);
    out.add_dense(w).unwrap();
    out
}

//! Proposed structured mask. Research/test module only; not a source profile.
use super::corelib::field::{CM31, M31, M31_HALF, QM31 as K};

pub(super) const N: usize = 1024;
pub(super) const ROUNDS: usize = 10;
pub(super) const PER_ROUND: usize = 27;
pub(super) const COINS: usize = 1 + ROUNDS * PER_ROUND;

fn scalar(i: usize) -> K {
    K::from_cm31(CM31::from_m31(M31(i as u32)))
}

pub(super) fn mixing_row(i: usize) -> Vec<K> {
    assert!(i < N);
    let node = scalar(i + 1);
    let mut power = K::ONE;
    (0..N)
        .map(|_| {
            let out = power;
            power = power.mul(node);
            out
        })
        .collect()
}

pub(super) fn mixed_coins(g: &[K]) -> [K; COINS] {
    assert_eq!(g.len(), N);
    core::array::from_fn(|i| {
        let node = scalar(i + 1);
        g.iter().rev().fold(K::ZERO, |v, &c| v.mul(node).add(c))
    })
}

fn zero_boundary(u: &[K], x: K) -> K {
    assert_eq!(u.len(), PER_ROUND);
    let mut out = u[0].mul(K::ONE.sub(x.add(x)));
    let mut power = x.square();
    for &c in &u[1..] {
        out = out.add(c.mul(power.sub(x)));
        power = power.mul(x);
    }
    out
}

pub(super) fn mask_eval(coins: &[K; COINS], point: &[K; ROUNDS]) -> K {
    let half = K::from_cm31(CM31::from_m31(M31_HALF));
    let mut scale = K::ONE;
    let mut out = K::ZERO;
    for r in (0..ROUNDS).rev() {
        let start = 1 + r * PER_ROUND;
        out = out.add(zero_boundary(&coins[start..start + PER_ROUND], point[r]).mul(scale));
        scale = scale.mul(half);
    }
    out.add(coins[0].mul(scale))
}

pub(super) fn round_coefficients(carry: K, u: &[K]) -> [K; 28] {
    assert_eq!(u.len(), PER_ROUND);
    let mut out = [K::ZERO; 28];
    out[0] = carry.mul_m31(M31_HALF).add(u[0]);
    out[1] = u[0].add(u[0]).neg();
    for (i, &v) in u[1..].iter().enumerate() {
        out[i + 2] = v;
        out[1] = out[1].sub(v);
    }
    out
}

pub(super) fn mask_weights(point: &[K; ROUNDS]) -> Vec<K> {
    let mut coin_weights = [K::ZERO; COINS];
    let mut scale = K::ONE;
    for r in (0..ROUNDS).rev() {
        let start = 1 + r * PER_ROUND;
        let x = point[r];
        coin_weights[start] = scale.mul(K::ONE.sub(x.add(x)));
        let mut power = x.square();
        for i in 1..PER_ROUND {
            coin_weights[start + i] = scale.mul(power.sub(x));
            power = power.mul(x);
        }
        scale = scale.mul_m31(M31_HALF);
    }
    coin_weights[0] = scale;
    let mut weights = vec![K::ZERO; N];
    for (i, &a) in coin_weights.iter().enumerate() {
        for (w, b) in weights.iter_mut().zip(mixing_row(i)) {
            *w = w.add(a.mul(b));
        }
    }
    weights
}

#[test]
fn r17_structured_g_round_algebra_and_functional() {
    fn sample(i: usize) -> K {
        let i = i as u32;
        K {
            c0: CM31::new(M31(i + 1), M31(3 * i + 7)),
            c1: CM31::new(M31(5 * i + 11), M31(7 * i + 13)),
        }
    }
    let g: Vec<_> = (0..N).map(sample).collect();
    let coins = mixed_coins(&g);
    for (i, &coin) in coins.iter().enumerate() {
        assert_eq!(
            coin,
            g.iter()
                .zip(mixing_row(i))
                .fold(K::ZERO, |v, (&a, b)| v.add(a.mul(b)))
        );
    }
    let z: [K; ROUNDS] = core::array::from_fn(|i| sample(1200 + i));
    let initial = (0..N).fold(K::ZERO, |sum, row| {
        let p = core::array::from_fn(|bit| scalar((row >> (9 - bit)) & 1));
        sum.add(mask_eval(&coins, &p))
    });
    assert_eq!(initial, coins[0]);
    let mut carry = initial;
    for round in 0..ROUNDS {
        let start = 1 + round * PER_ROUND;
        let u = &coins[start..start + PER_ROUND];
        let coeff = round_coefficients(carry, u);
        let eval = |x| coeff.iter().rev().fold(K::ZERO, |v, &a| v.mul(x).add(a));
        assert_eq!(eval(K::ZERO).add(eval(K::ONE)), carry);
        // The source sends c0,c2,...,c27. Their inverse recovers exactly u.
        assert_eq!(coeff[0].sub(carry.mul_m31(M31_HALF)), u[0]);
        assert_eq!(&coeff[2..], &u[1..]);
        for x in (0..28).map(scalar).chain(core::iter::once(z[round])) {
            let suffix_bits = ROUNDS - 1 - round;
            let direct = (0..1 << suffix_bits).fold(K::ZERO, |sum, suffix| {
                let mut p = z;
                p[round] = x;
                for b in 0..suffix_bits {
                    p[round + 1 + b] = scalar((suffix >> (suffix_bits - 1 - b)) & 1);
                }
                sum.add(mask_eval(&coins, &p))
            });
            assert_eq!(direct, eval(x), "round={round}");
        }
        carry = eval(z[round]);
    }
    let terminal = mask_eval(&coins, &z);
    assert_eq!(carry, terminal);
    assert_eq!(
        terminal,
        g.iter()
            .zip(mask_weights(&z))
            .fold(K::ZERO, |v, (&a, b)| v.add(a.mul(b)))
    );
    println!("R17_STRUCTURED_G coins=271 rounds=10 suffix_checks=290 boundary_checks=10 terminal_functional=true");
}

#[test]
fn r17_structured_g_unchanged_shared_functional_negative() {
    use aspis_core::sumcheck::WeightAccumulator;
    let z = core::array::from_fn(|i| scalar(i + 2));
    let wg = mask_weights(&z);
    let mut ordinary = WeightAccumulator::empty(10);
    ordinary.add_multilinear(K::ONE, z.to_vec()).unwrap();
    let inactive = &super::basis_transport::transport().inactive;
    let anchor = (0..N).find(|&i| inactive[i]).unwrap();
    let difference = |i: usize| wg[i].sub(ordinary.weight_at(i as u32));
    let row = (0..N)
        .find(|&i| inactive[i] && difference(i) != difference(anchor))
        .unwrap();
    let gamma = scalar(7);
    // Algebraic collision in the single batched message, not a forged source
    // proof: H1 changes by -gamma*d and G by d. Both are QM31 columns.
    let mut dh = vec![K::ZERO; N];
    let mut dg = vec![K::ZERO; N];
    dh[row] = gamma.neg();
    dh[anchor] = gamma;
    dg[row] = K::ONE;
    dg[anchor] = K::ONE.neg();
    let mut h1 = vec![K::ZERO; N];
    crate::state_only_hiding::apply_pool_v1_pair_forest_h1_padding_mask_v1(&mut h1, &dh).unwrap();
    assert_eq!(h1, dh);
    let gh = gamma.pow(26);
    let gg = gamma.pow(27);
    assert!((0..N).all(|i| gh.mul(dh[i]).add(gg.mul(dg[i])) == K::ZERO));
    let ordinary_delta = ordinary
        .weight_at(row as u32)
        .sub(ordinary.weight_at(anchor as u32));
    let proposed_claim_change = gh
        .mul(gamma.neg().mul(ordinary_delta))
        .add(gg.mul(wg[row].sub(wg[anchor])));
    assert_ne!(proposed_claim_change, K::ZERO);
    // A new common functional cannot fix this: every linear functional of
    // the zero combined message is zero, while the required claim is not.
    println!("R17_SHARED_FUNCTIONAL_NEGATIVE rows={anchor},{row} legal_h1_pad=true combined_delta=0 required_claim_delta_nonzero=true");
}

