// GENERATED by refine/glue/gen-glue.py.txt from the glue table; do not edit.
// The same table renders the Lean text checked verbatim in R0Z/BuilderBlocksChain,
// BuilderWitness, BuilderWitnessTree and BuilderWitnessTrace.

fn init_owner() -> [u32; 16] { bw::sponge_init(0x41530001, 8) }
fn init_note() -> [u32; 16] { bw::sponge_init(0x41530003, 18) }
fn init_nul() -> [u32; 16] { bw::sponge_init(0x41530002, 16) }

fn sponge_pre(w: &RW, p: &RP, h: usize) -> [u32; 16] {
    match h {
        0 => init_owner(),
        1 => init_note(),
        2 => sponge_step(init_note(), schunk(w, p, 1), sclen(1)),
        3 => sponge_step(sponge_step(init_note(), schunk(w, p, 1), sclen(1)), schunk(w, p, 2), sclen(2)),
        25 => init_nul(),
        26 => sponge_step(init_nul(), schunk(w, p, 25), sclen(25)),
        27 => init_note(),
        28 => sponge_step(init_note(), schunk(w, p, 27), sclen(27)),
        29 => sponge_step(sponge_step(init_note(), schunk(w, p, 27), sclen(27)), schunk(w, p, 28), sclen(28)),
        30 => init_note(),
        31 => sponge_step(init_note(), schunk(w, p, 30), sclen(30)),
        32 => sponge_step(sponge_step(init_note(), schunk(w, p, 30), sclen(30)), schunk(w, p, 31), sclen(31)),
        _ => [0u32; 16],
    }
}

fn schunk(w: &RW, p: &RP, h: usize) -> [u32; 8] {
    if h == 0 || h == 25 { w.sk
    } else if h == 1 { owner_d(w)
    } else if h == 2 { note_c2r(w.input_value, p.asset, &w.salt)
    } else if h == 3 { note_c3r(&w.salt)
    } else if h == 26 { w.salt
    } else if h == 27 { w.recipient_owner
    } else if h == 28 { note_c2r(w.output_value, p.asset, &w.recipient_salt)
    } else if h == 29 { note_c3r(&w.recipient_salt)
    } else if h == 30 { w.change_owner
    } else if h == 31 { note_c2r(w.change_value, p.asset, &w.change_salt)
    } else if h == 32 { note_c3r(&w.change_salt)
    } else { ZERO8 }
}

fn sclen(h: usize) -> usize { if h == 3 || h == 29 || h == 32 { 2 } else { 8 } }

fn children(w: &RW, p: &RP, h: usize) -> ([u32; 8], [u32; 8]) {
    if 4 <= h && h <= 24 { ordered_r(tree_cur_r(w, p, h - 4), w.sibs[h - 4], bit_b(w, h - 4)) }
    else if 54 <= h { ordered_r(tree_cur_r(w, p, h - 33), w.sibs[h - 33], bit_b(w, h - 33)) }
    else if h == 33 {
        if p.transfer { (recip_dr(w, p), change_dr(w, p)) } else { (change_dr(w, p), ZERO8) }
    }
    else if 34 <= h && h <= 53 { ordered_r(app_cur_r(w, p, h - 34), app_sib_r(p, h - 34), app_bit_r(p, h - 34)) }
    else { (ZERO8, ZERO8) }
}

const PATH_ROW0: usize = 912;
const AUX_ROW0: usize = 1008;
const C1_COLS: usize = 16;
